(* Run latch *)
IF Start_PB AND NOT Stop_PB AND Emergency_Stop
   AND NOT Overload AND NOT Fault_State THEN
    Run_Latch := TRUE;
END_IF;
IF NOT Stop_PB OR NOT Emergency_Stop OR Overload THEN
    Run_Latch := FALSE;
END_IF;

(* Outputs *)
Motor_Run  := Run_Latch AND NOT Fault_State;
Ready_Lamp := NOT Fault_State AND NOT Motor_Run;
Fault_Lamp := Fault_State OR Overload;
